// The tombstone-lifecycle task 2.6 adoption-safety guards: the live-status
// Adopt fire guard and the derive-walk exclusion (D4 amendment rulings (i)
// and (iii)). A deleted row is never derived, never dispatched, never
// stripped, and its settle never fires Adopt — its retained stock survives
// every queue pass byte-intact.

// TestWorkItemSkipsAdoptForDeletedRow pins the fire guard: a deleted row's
// settle never fires the Adopt dep (a recording dep proves zero fires — the
// row would otherwise become its own identity-matching candidate and the
// self-move DELETE would destroy its stock), while a live row's settle still
// fires exactly once.
func TestWorkItemSkipsAdoptForDeletedRow(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}

	// Both docs carry every queueable namespace (tv-parser, tmdb, frame-grabber
	// — the tv chain's queueable set; kinopoisk is CLIENT), so a workItem pass
	// drives no source — the pass is settle-only, isolating the Adopt fire
	// decision.
	settled := baseDoc("Show/S01E01.mkv")
	settled["sources"] = map[string]any{
		"tv-parser":     map[string]any{"title": "done"},
		"tmdb":          map[string]any{"title": "done"},
		"frame-grabber": map[string]any{"title": "done"},
	}
	putItem(t, s, "itm_adopt_dead", libID, statusDeleted, settled)
	putItem(t, s, "itm_adopt_live", libID, statusEnriched, settled)

	fires := 0
	q := NewQueue(Deps{Store: s, Modules: reg, Adopt: func(context.Context, string) { fires++ }}, QueueConfig{})

	q.workItem(ctx, "itm_adopt_dead")
	if fires != 0 {
		t.Fatalf("Adopt fired %d times for a deleted row's settle, want 0", fires)
	}
	waitForStatus(t, s, "itm_adopt_dead", statusDeleted, time.Second) // dead posture untouched

	q.workItem(ctx, "itm_adopt_live")
	if fires != 1 {
		t.Fatalf("Adopt fired %d times for a live row's settle, want exactly 1", fires)
	}
	waitForStatus(t, s, "itm_adopt_live", statusReady, 2*time.Second)
}

// TestDeriveSkipsDeletedRows pins the walk exclusion: the shared allItems/
// allSeries walks feed deriveLibrary AND reenrichScope, so a deleted row is
// never derived (a namespace-free dead doc would otherwise derive its whole
// chain pending and re-dispatch forever — the 2.4 red loop), a live sibling's
// derivation is unaffected, and the reenrich scope likewise skips dead rows
// (stripping a tombstoned row's namespace would destroy self-heal's D3
// namespace carry-forward).
func TestDeriveSkipsDeletedRows(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}

	// Fresh-scan posture on both sides: no namespaces, so a live row derives
	// its whole chain pending and a dead row would too — absent the exclusion.
	putItem(t, s, "itm_dead_fresh", libID, statusDeleted, baseDoc("Dead/S01E01.mkv"))
	putItem(t, s, "itm_live_fresh", libID, statusPending, baseDoc("Live/S01E01.mkv"))
	deadSeriesID := putSeriesRow(t, s, "tv", libID, "Dead", statusDeleted, map[string]any{})
	liveSeriesID := putSeriesRow(t, s, "tv", libID, "Live", statusPending, map[string]any{})

	q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
	tasks, err := q.deriveLibrary(ctx, libID)
	if err != nil {
		t.Fatalf("deriveLibrary: %v", err)
	}
	for _, tk := range tasks {
		if tk.rowID == "itm_dead_fresh" || tk.rowID == deadSeriesID {
			t.Fatalf("dead row %s derived a task — the walk exclusion leaked: %+v", tk.rowID, tk)
		}
	}
	rowTasks := func(rowID string) map[string]bool {
		out := map[string]bool{}
		for _, tk := range tasks {
			if tk.rowID == rowID {
				out[tk.pluginID] = true
			}
		}
		return out
	}
	if got := rowTasks("itm_live_fresh"); !got["tv-parser"] || !got["tmdb"] || !got["frame-grabber"] {
		t.Fatalf("live sibling derivation = %v, want the full chain unaffected (tv-parser + tmdb + frame-grabber)", got)
	}
	if got := rowTasks(liveSeriesID); !got["tv-parser"] || !got["tmdb"] || !got["frame-grabber"] {
		t.Fatalf("live series derivation = %v, want the full chain unaffected (tv-parser + tmdb + frame-grabber)", got)
	}

	// The reenrich scope walks the same helpers: a dead row carrying the
	// namespace must never be scoped (never stripped).
	nsDoc := baseDoc("Dead/S01E02.mkv")
	nsDoc["sources"] = map[string]any{"tv-parser": map[string]any{"title": "done"}}
	putItem(t, s, "itm_dead_ns", libID, statusDeleted, nsDoc)
	liveNsDoc := baseDoc("Live/S01E02.mkv")
	liveNsDoc["sources"] = map[string]any{"tv-parser": map[string]any{"title": "done"}}
	putItem(t, s, "itm_live_ns", libID, statusPending, liveNsDoc)
	deadNsSeriesID := putSeriesRow(t, s, "tv", libID, "DeadNs", statusDeleted, map[string]any{
		"sources": map[string]any{"tv-parser": map[string]any{"title": "done"}},
	})

	scope, err := q.reenrichScope(ctx, libID, "tv-parser", nil)
	if err != nil {
		t.Fatalf("reenrichScope: %v", err)
	}
	scoped := map[string]bool{}
	for _, id := range scope {
		scoped[id] = true
	}
	for _, dead := range []string{"itm_dead_ns", deadNsSeriesID} {
		if scoped[dead] {
			t.Fatalf("reenrich scope includes dead row %s — a strip would destroy self-heal's carry-forward", dead)
		}
	}
	if !scoped["itm_live_ns"] {
		t.Fatalf("reenrich scope misses live namespaced row itm_live_ns: %v", scope)
	}
}
